(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla-js';
  var uid = 0;

  /**
   * @planks-provisional("features/app-initialization.feature:TodoApp constructor initializes the application on instantiation")
   */
  function TodoApp() {
    this.todos = [];
    this.filter = 'all';
    this.editingId = null;
    this._editCancelled = false;
    this.init();
  }

  /**
   * @planks-provisional("features/app-initialization.feature:TodoApp constructor initializes the application on instantiation")
   */
  TodoApp.prototype.init = function () {
    this.load();
    this.render();
    this.bindEvents();
    this.handleRoute();
  };

  /**
   * @planks("the page has stored two todos in localStorage")
   * @planks("localStorage key {string} contains a todo with title {string} and completed true")
   */
  TodoApp.prototype.load = function () {
    try {
      this.todos = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      this.todos = [];
    }
  };

  /**
   * @planks("localStorage key {string} contains a todo with title {string} and completed true")
   */
  TodoApp.prototype.save = function () {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
  };

  /**
   * @planks("{string} is added to the todo list")
   */
  TodoApp.prototype.addTodo = function (title) {
    title = title.trim();
    if (!title) return;
    this.todos.push({ id: ++uid, title: title, completed: false });
    this.save();
    this.render();
  };

  /**
   * @planks("{string} is removed from the todo list")
   */
  TodoApp.prototype.destroyTodo = function (id) {
    this.todos = this.todos.filter(function (t) { return t.id !== id; });
    this.editingId = null;
    this.save();
    this.render();
  };

  /**
   * @planks("{string} has the class {string}")
   */
  TodoApp.prototype.toggleTodo = function (id) {
    var todo = this.todos.find(function (t) { return t.id === id; });
    if (todo) {
      todo.completed = !todo.completed;
      this.save();
      this.render();
    }
  };

  /**
   * @planks("the todo title is updated to {string}")
   * @planks("{string} is removed from the todo list")
   */
  TodoApp.prototype.editTodo = function (id, title) {
    title = title.trim();
    if (!title) {
      this.destroyTodo(id);
      return;
    }
    var todo = this.todos.find(function (t) { return t.id === id; });
    if (todo) {
      todo.title = title;
      this.save();
    }
    this.editingId = null;
    this.render();
  };

  /**
   * @planks("the clear completed button is hidden")
   * @planks("{string} is removed from the todo list")
   */
  TodoApp.prototype.clearCompleted = function () {
    this.todos = this.todos.filter(function (t) { return !t.completed; });
    this.save();
    this.render();
  };

  /**
   * @planks("all todos are marked as complete")
   * @planks("all todos are marked as active")
   */
  TodoApp.prototype.toggleAll = function (checked) {
    this.todos.forEach(function (t) { t.completed = checked; });
    this.save();
    this.render();
  };

  /**
   * @planks("the main section is hidden")
   * @planks("the footer is hidden")
   */
  TodoApp.prototype.render = function () {
    var main = document.querySelector('.main');
    var footer = document.querySelector('.footer');
    var todoList = document.querySelector('.todo-list');

    if (this.todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = '';
      footer.style.display = '';
    }

    this.renderTodoList();
    this.renderCounter();
    this.renderToggleAll();
    this.renderClearCompleted();
    this.renderFilters();
  };

  /**
   * @planks("{string} is added to the todo list")
   * @planks("{string} enters editing mode")
   * @planks("the edit input is focused with value {string}")
   */
  TodoApp.prototype.renderTodoList = function () {
    var self = this;
    var todoList = document.querySelector('.todo-list');
    todoList.innerHTML = '';

    var visible = this.getVisibleTodos();

    this.todos.forEach(function (todo) {
      var isVisible = visible.indexOf(todo) !== -1;
      var li = document.createElement('li');
      li.dataset.id = String(todo.id);
      if (todo.completed) li.classList.add('completed');
      if (self.editingId === todo.id) li.classList.add('editing');
      if (!isVisible) li.style.display = 'none';

      var view = document.createElement('div');
      view.className = 'view';

      var toggle = document.createElement('input');
      toggle.className = 'toggle';
      toggle.type = 'checkbox';
      toggle.checked = todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroy = document.createElement('button');
      destroy.className = 'destroy';

      view.appendChild(toggle);
      view.appendChild(label);
      view.appendChild(destroy);

      var edit = document.createElement('input');
      edit.className = 'edit';
      edit.value = todo.title;

      li.appendChild(view);
      li.appendChild(edit);
      todoList.appendChild(li);
    });

    if (self.editingId !== null) {
      var el = todoList.querySelector('li.editing .edit');
      if (el) el.focus();
    }
  };

  /**
   * @planks("the counter shows {string}")
   */
  TodoApp.prototype.renderCounter = function () {
    var counter = document.querySelector('.todo-count');
    var active = this.todos.filter(function (t) { return !t.completed; }).length;
    var word = active === 1 ? 'item' : 'items';
    counter.innerHTML = '<strong>' + active + '</strong> ' + word + ' left';
  };

  /**
   * @planks("the toggle-all checkbox is checked")
   * @planks("the toggle-all checkbox is unchecked")
   */
  TodoApp.prototype.renderToggleAll = function () {
    var toggleAll = document.querySelector('.toggle-all');
    var allCompleted = this.todos.length > 0 &&
      this.todos.every(function (t) { return t.completed; });
    toggleAll.checked = allCompleted;
  };

  /**
   * @planks("the clear completed button is hidden")
   */
  TodoApp.prototype.renderClearCompleted = function () {
    var btn = document.querySelector('.clear-completed');
    if (this.todos.some(function (t) { return t.completed; })) {
      btn.style.display = '';
    } else {
      btn.style.display = 'none';
    }
  };

  /**
   * @planks("the {string} filter link has the class {string}")
   */
  TodoApp.prototype.renderFilters = function () {
    var self = this;
    var filterMap = { all: '#/', active: '#/active', completed: '#/completed' };
    var expected = filterMap[self.filter] || '#/';
    document.querySelectorAll('.filters a').forEach(function (a) {
      if (a.getAttribute('href') === expected) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    });
  };

  /**
   * @planks("I navigate to {string}")
   * @planks("the page is reloaded")
   */
  TodoApp.prototype.handleRoute = function () {
    var hash = location.hash || '#/';
    if (hash === '#/active') this.filter = 'active';
    else if (hash === '#/completed') this.filter = 'completed';
    else this.filter = 'all';
    this.renderFilters();
  };

  /**
   * @planks("{string} is hidden")
   * @planks("all todos are visible")
   */
  TodoApp.prototype.getVisibleTodos = function () {
    if (this.filter === 'active') return this.todos.filter(function (t) { return !t.completed; });
    if (this.filter === 'completed') return this.todos.filter(function (t) { return t.completed; });
    return this.todos.slice();
  };

  /**
   * @planks("the page is open")
   * @planks("I type {string} in the new todo input")
   * @planks("I press Enter")
   * @planks("I check the toggle-all checkbox")
   * @planks("I click the toggle checkbox for {string}")
   * @planks("I click the destroy button for {string}")
   * @planks("I double-click the label of {string}")
   * @planks("I press Escape")
   * @planks("I blur the edit input")
   * @planks("I clear the edit input and type {string}")
   * @planks("I click the clear completed button")
   */
  TodoApp.prototype.bindEvents = function () {
    var self = this;

    window.addEventListener('hashchange', function () {
      self.handleRoute();
      self.render();
    });

    var newTodo = document.querySelector('.new-todo');
    newTodo.addEventListener('keydown', function (e) {
      if (e.key === 'Enter') {
        var val = newTodo.value.trim();
        if (val) {
          self.addTodo(val);
          newTodo.value = '';
        }
      }
    });

    var toggleAll = document.querySelector('.toggle-all');
    toggleAll.addEventListener('change', function () {
      self.toggleAll(toggleAll.checked);
    });

    var todoList = document.querySelector('.todo-list');

    todoList.addEventListener('click', function (e) {
      if (e.target.classList.contains('toggle')) {
        var li = e.target.closest('li');
        self.toggleTodo(Number(li.dataset.id));
      }
      if (e.target.classList.contains('destroy')) {
        var li = e.target.closest('li');
        self.destroyTodo(Number(li.dataset.id));
      }
    });

    todoList.addEventListener('dblclick', function (e) {
      if (e.target.tagName === 'LABEL') {
        var li = e.target.closest('li');
        self.editingId = Number(li.dataset.id);
        self._editCancelled = false;
        self.render();
      }
    });

    todoList.addEventListener('keydown', function (e) {
      if (e.target.classList.contains('edit')) {
        if (e.key === 'Enter') {
          var li = e.target.closest('li');
          self.editTodo(Number(li.dataset.id), e.target.value);
        }
        if (e.key === 'Escape') {
          var li = e.target.closest('li');
          var todo = self.todos.find(function (t) { return t.id === Number(li.dataset.id); });
          if (todo) e.target.value = todo.title;
          self._editCancelled = true;
          self.editingId = null;
          e.target.blur();
        }
      }
    });

    todoList.addEventListener('focusout', function (e) {
      if (e.target.classList.contains('edit')) {
        if (self._editCancelled) {
          self._editCancelled = false;
          self.render();
          return;
        }
        if (self.editingId !== null) {
          var li = e.target.closest('li');
          self.editTodo(Number(li.dataset.id), e.target.value);
        }
      }
    });

    var clearBtn = document.querySelector('.clear-completed');
    clearBtn.addEventListener('click', function () {
      self.clearCompleted();
    });
  };

  /**
   * @planks-provisional("features/app-infrastructure.feature:TodoApp exposes itself as a window global on startup")
   */
  window.App = TodoApp;
  window.app = new TodoApp();
})();

{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

/* ── navigation and page lifecycle ── */

Given('the page is open', function () {
  /* page loaded in World constructor */
});

When('the page loads', function () {
  /* page loaded in World constructor */
});

When('the page is reloaded', function () {
  const { Window } = require('happy-dom');
  const fs = require('fs');
  const path = require('path');

  /* preserve localStorage and hash across reload */
  const storedKeys = {};
  for (let i = 0; i < this.window.localStorage.length; i++) {
    const key = this.window.localStorage.key(i);
    storedKeys[key] = this.window.localStorage.getItem(key);
  }
  const prevHash = this.window.location.hash;

  this.window = new Window({ url: 'http://localhost:3000/' });
  this.document = this.window.document;

  /* restore localStorage and hash */
  Object.keys(storedKeys).forEach(function (key) {
    this.window.localStorage.setItem(key, storedKeys[key]);
  }.bind(this));
  if (prevHash) this.window.location.hash = prevHash;

  const htmlPath = path.join(__dirname, '..', '..', 'src', 'index.html');
  const html = fs.readFileSync(htmlPath, 'utf-8');
  this.document.body.innerHTML = html;

  const appPath = path.join(__dirname, '..', '..', 'src', 'app.js');
  const appCode = fs.readFileSync(appPath, 'utf-8');
  this.window.eval(appCode);

  this.app = this.window.app;
  this._editingTodoId = null;
});

When('I navigate to {string}', function (hash) {
  this.window.location.hash = hash.replace(/^#/, '');
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

/* ── todo setup ── */

Given('the following todos exist:', function (dataTable) {
  dataTable.rows().forEach(function (row) {
    this.app.addTodo(row[0]);
    if (row[1] === 'true') {
      var todo = this.app.todos.find(function (t) { return t.title === row[0]; });
      if (todo) {
        todo.completed = true;
        this.app.save();
      }
    }
  }.bind(this));
  this.app.render();
});

Given('the todo {string} exists', function (title) {
  this.app.addTodo(title);
});

Given('the completed todo {string} exists', function (title) {
  this.app.addTodo(title);
  var todo = this.app.todos.find(function (t) { return t.title === title; });
  if (todo) {
    todo.completed = true;
    this.app.save();
    this.app.render();
  }
});

Given('the todo {string} is in editing mode', function (title) {
  this.app.addTodo(title);
  var todo = this.app.todos.find(function (t) { return t.title === title; });
  if (todo) {
    this.app.editingId = todo.id;
    this.app._editCancelled = false;
    this.app.render();
    this._editingTodoId = todo.id;
  }
});

Given('the page has stored two todos in localStorage', function () {
  this.window.localStorage.setItem('todos-vanilla-js', JSON.stringify([
    { id: 1, title: 'First todo', completed: false },
    { id: 2, title: 'Second todo', completed: true }
  ]));
});

/* ── input actions ── */

When('I type {string} in the new todo input', function (text) {
  var input = this.document.querySelector('.new-todo');
  input.focus();
  input.value = text;
});

When('I press Enter', function () {
  var el = this.document.activeElement;
  if (el && el.classList.contains('new-todo')) {
    el.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  } else if (el && el.classList.contains('edit')) {
    el.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  }
});

When('I press Escape', function () {
  var el = this.document.activeElement;
  if (el && el.classList.contains('edit')) {
    el.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  }
});

/* ── toggle actions ── */

When('I check the toggle-all checkbox', function () {
  var cb = this.document.querySelector('.toggle-all');
  cb.checked = !cb.checked;
  cb.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I complete the todo {string}', function (title) {
  var li = this.findTodoLi(title);
  var toggle = li.querySelector('.toggle');
  toggle.click();
});

When('I click the toggle checkbox for {string}', function (title) {
  var li = this.findTodoLi(title);
  var toggle = li.querySelector('.toggle');
  toggle.click();
});

/* ── destroy actions ── */

When('I click the destroy button for {string}', function (title) {
  var li = this.findTodoLi(title);
  var destroy = li.querySelector('.destroy');
  destroy.click();
});

/* ── editing actions ── */

When('I double-click the label of {string}', function (title) {
  var li = this.findTodoLi(title);
  var label = li.querySelector('label');
  var todo = this.app.todos.find(function (t) { return t.title === title; });
  if (todo) this._editingTodoId = todo.id;
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I clear the edit input', function () {
  var edit = this.document.querySelector('.todo-list .edit');
  if (edit) { edit.focus(); edit.value = ''; }
});

When('I clear the edit input and type {string}', function (text) {
  var edit = this.document.querySelector('.todo-list .edit');
  if (edit) { edit.focus(); edit.value = text; }
});

When('I blur the edit input', function () {
  var edit = this.document.querySelector('.todo-list .edit');
  if (edit) { edit.focus(); edit.blur(); }
});

When('I hover over the todo {string}', function (title) {
  /* hover is visual; no DOM state change needed */
});

/* ── clear completed ── */

When('I click the clear completed button', function () {
  this.document.querySelector('.clear-completed').click();
});

/* ── assertions: visibility ── */

Then('the main section is hidden', function () {
  var main = this.document.querySelector('.main');
  assert.strictEqual(main.style.display, 'none', 'main section should be hidden');
});

Then('the footer is hidden', function () {
  var footer = this.document.querySelector('.footer');
  assert.strictEqual(footer.style.display, 'none', 'footer should be hidden');
});

Then('all todos are visible', function () {
  var items = this.document.querySelectorAll('.todo-list li');
  items.forEach(function (li) {
    assert.notStrictEqual(li.style.display, 'none', 'todo should be visible');
  });
});

Then('only {string} is visible', function (title) {
  var items = this.document.querySelectorAll('.todo-list li');
  var found = false;
  items.forEach(function (li) {
    var label = li.querySelector('label');
    if (label && label.textContent === title) {
      found = true;
      assert.notStrictEqual(li.style.display, 'none');
    }
  });
  assert.ok(found, 'Todo "' + title + '" should be in the list');
});

Then('{string} is hidden', function (title) {
  var li = this.findTodoLi(title);
  var style = li.style.display;
  assert.strictEqual(style, 'none', 'Todo "' + title + '" should be hidden');
});

Then('only active todos are visible', function () {
  var items = this.document.querySelectorAll('.todo-list li');
  items.forEach(function (li) {
    assert.ok(!li.classList.contains('completed') || li.style.display === 'none',
      'completed todos should be hidden in active filter');
  });
});

/* ── assertions: todo state ── */

Then('{string} is added to the todo list', function (title) {
  var li = this.findTodoLi(title);
  assert.ok(li, 'Todo "' + title + '" should exist in the list');
});

Then('the new todo input is cleared', function () {
  var input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'new todo input should be cleared');
});

Then('the counter shows {string}', function (expected) {
  var counter = this.document.querySelector('.todo-count');
  assert.strictEqual(counter.textContent, expected,
    'counter should show "' + expected + '"');
});

Then('no todo is added to the list', function () {
  var items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'no todos should be in the list');
});

Then('all todos are marked as complete', function () {
  this.document.querySelectorAll('.todo-list li').forEach(function (li) {
    assert.ok(li.classList.contains('completed'),
      'each todo should have completed class');
  });
});

Then('all todos are marked as active', function () {
  this.document.querySelectorAll('.todo-list li').forEach(function (li) {
    assert.ok(!li.classList.contains('completed'),
      'each todo should not have completed class');
  });
});

Then('the toggle-all checkbox is checked', function () {
  var cb = this.document.querySelector('.toggle-all');
  assert.ok(cb.checked, 'toggle-all checkbox should be checked');
});

Then('the toggle-all checkbox is unchecked', function () {
  var cb = this.document.querySelector('.toggle-all');
  assert.ok(!cb.checked, 'toggle-all checkbox should be unchecked');
});

Then('{string} has the class {string}', function (title, cls) {
  var li = this.findTodoLi(title);
  assert.ok(li.classList.contains(cls),
    'Todo "' + title + '" should have class "' + cls + '"');
});

Then('{string} does not have the class {string}', function (title, cls) {
  var li = this.findTodoLi(title);
  assert.ok(!li.classList.contains(cls),
    'Todo "' + title + '" should not have class "' + cls + '"');
});

Then('the destroy button for {string} is visible', function (title) {
  var li = this.findTodoLi(title);
  var destroy = li.querySelector('.destroy');
  assert.ok(destroy, 'destroy button should exist for "' + title + '"');
});

Then('{string} is removed from the todo list', function (title) {
  var li = this.findTodoLiOrNull(title);
  assert.strictEqual(li, null, 'Todo "' + title + '" should be removed');
});

Then('{string} remains in the todo list', function (title) {
  var li = this.findTodoLi(title);
  assert.ok(li, 'Todo "' + title + '" should remain');
});

/* ── assertions: editing ── */

Then('{string} enters editing mode', function (title) {
  var li = this.findTodoLi(title);
  assert.ok(li.classList.contains('editing'),
    'Todo "' + title + '" should be in editing mode');
});

Then('{string} exits editing mode', function (title) {
  /* The todo may have been renamed or destroyed during editing.
     Look for the todo that was being edited by its tracked id. */
  if (this._editingTodoId) {
    var li = this.document.querySelector(
      '.todo-list li[data-id="' + this._editingTodoId + '"]');
    if (li) {
      assert.ok(!li.classList.contains('editing'),
        'Todo should not be in editing mode');
    }
    /* If li does not exist, todo was destroyed; editing mode is exited by definition */
  } else {
    /* Fallback: no todo should be in editing mode */
    var editing = this.document.querySelectorAll('.todo-list li.editing');
    assert.strictEqual(editing.length, 0, 'no todo should be in editing mode');
  }
});

Then('the edit input is focused with value {string}', function (val) {
  var edit = this.document.querySelector('.todo-list .edit');
  assert.ok(edit, 'edit input should exist');
  assert.strictEqual(edit.value, val, 'edit input value should be "' + val + '"');
});

Then('the todo title is updated to {string}', function (title) {
  var found = this.app.todos.find(function (t) { return t.title === title; });
  assert.ok(found, 'Todo with title "' + title + '" should exist');
  var li = this.findTodoLi(title);
  assert.ok(li, 'Todo "' + title + '" should be in the DOM');
});

Then('the todo title remains {string}', function (title) {
  var li = this.findTodoLi(title);
  var label = li.querySelector('label');
  assert.strictEqual(label.textContent, title,
    'Todo label should remain "' + title + '"');
});

/* ── assertions: clear completed ── */

Then('the clear completed button is hidden', function () {
  var btn = this.document.querySelector('.clear-completed');
  assert.strictEqual(btn.style.display, 'none',
    'clear completed button should be hidden');
});

/* ── assertions: persistence ── */

Then('localStorage key {string} contains a todo with title {string} and completed true',
  function (key, title) {
    var raw = this.window.localStorage.getItem(key);
    assert.ok(raw, 'localStorage key "' + key + '" should exist');
    var todos = JSON.parse(raw);
    var found = todos.find(function (t) { return t.title === title; });
    assert.ok(found, 'Todo "' + title + '" should be in localStorage');
    assert.ok(found.completed, 'Todo "' + title + '" should be completed');
  });

Then('both stored todos are displayed in the todo list', function () {
  var items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length >= 2,
    'at least 2 todos should be displayed, found ' + items.length);
});

/* ── assertions: routing ── */

Then('the {string} filter link has the class {string}', function (name, cls) {
  var links = this.document.querySelectorAll('.filters a');
  var link = null;
  links.forEach(function (a) {
